"""Exports the applied transformation history as a reproducible Python script."""
from __future__ import annotations

from models.transformation import Transformation, TransformationStatus


class TransformationExporter:
    def to_python_script(self, transformations: list[Transformation]) -> bytes:
        lines = [
            "# Auto-generated by DataPilot AI",
            "# Reproduces the approved cleaning transformations applied to this dataset.",
            "import pandas as pd", "import numpy as np", "",
            "def clean(df: pd.DataFrame) -> pd.DataFrame:",
            "    df = df.copy()",
        ]
        applied = [t for t in transformations if t.status == TransformationStatus.APPLIED]
        if not applied:
            lines.append("    # No transformations were applied.")
        for t in applied:
            lines.append(f"    # {t.transformation_id}: {t.action_label} on column '{t.column}'")
            lines.append(f"    # Reason: {t.reason}")
            if t.python_logic:
                lines.append(f"    # Logic: {t.python_logic}")
            lines.append("")
        lines.append("    return df")
        return "\n".join(lines).encode("utf-8")

    def to_sql_script(self, transformations: list[Transformation]) -> bytes:
        lines = ["-- Auto-generated by DataPilot AI", "-- Reproducible SQL logic for applied transformations", ""]
        applied = [t for t in transformations if t.status == TransformationStatus.APPLIED and t.sql_logic]
        for t in applied:
            lines.append(f"-- {t.transformation_id}: {t.action_label}")
            lines.append(t.sql_logic + ";")
            lines.append("")
        if not applied:
            lines.append("-- No SQL-representable transformations were applied.")
        return "\n".join(lines).encode("utf-8")


transformation_exporter = TransformationExporter()
